1	import type {ChatSession} from '../types/session.js';
2	import type {ToolRegistry, ToolContext, ToolResponse} from './tools/registry.js';
3	import type {
4	  AIProvider,
5	  Message,
6	  MessageChunk,
7	  SendMessageParams,
8	  ToolCall,
9	  ToolResultContent,
10	  UsageMetadata,
11	} from '../types/ai.js';
12	import type {OutgoingMessage} from '../types/messages.js';
13	import type {PromptBuilder, PromptBuilderOptions} from '../infrastructure/builders/promptBuilder.js';
14	import type {SessionStore} from '../types/sessionStore.js';
15	import {toMessages, createContextConfig} from './conversationContext.js';
16	import type {ContextConfig} from './conversationContext.js';
17	import {
18	  shouldContinueToolLoop,
19	  collectText,
20	  buildToolCallMessages,
21	  collectToolCalls,
22	  extractStopReason,
23	  extractUsage,
24	} from './orchestratorHelpers.js';
25	import {appendEntry, commitStreamingEntries} from './entryMutations.js';
26	import {log} from '../shared/logger.js';
27	
28	const DEFAULT_MAX_TOOL_ROUNDS = 5;
29	
30	export interface OrchestratorHooks {
31	  beforeSession?: (session: ChatSession) => Promise<void>;
32	  afterSession?: (session: ChatSession) => Promise<void>;
33	  beforeUserInput?: (session: ChatSession, userMessage: string) => Promise<string>;
34	  afterUserInput?: (session: ChatSession, userMessage: string) => Promise<void>;
35	  beforeModelResponse?: (session: ChatSession, systemPrompt: string) => Promise<string>;
36	  afterModelResponse?: (session: ChatSession, responseText: string, totalUsage?: UsageMetadata) => Promise<void>;
37	  onError?: (session: ChatSession, error: Error) => Promise<void>;
38	  /** The supported seam for an EU AI Act Art. 14 human-oversight control: fires before each known tool's executor, and a returned ToolResponse replaces the call (see docs/adding-a-tool.md); it receives the model's raw tool input and, through session, the caller's authHeaders, so a policy that logs either logs personal data and credential material; the engine asserts nothing about any policy installed here. */
39	  beforeToolCall?: (session: ChatSession, call: ToolCall) => Promise<ToolResponse | undefined>;
40	  /** Fires when the model asks for a tool round the budget refuses, after the last provider call and before afterModelResponse; a returned string reaches the user as the turn's closing text, and the engine writes none of its own (see specs/hal-engine-tool-budget/spec.md). */
41	  onToolBudgetExhausted?: (session: ChatSession, budget: ToolBudgetInfo) => Promise<string | undefined>;
42	}
43	
44	export interface ToolBudgetInfo {
45	  maxToolRounds: number;
46	  requestedTools: string[];
47	}
48	
49	type BeforeToolCall = NonNullable<OrchestratorHooks['beforeToolCall']>;
50	type OnToolBudgetExhausted = NonNullable<OrchestratorHooks['onToolBudgetExhausted']>;
51	
52	export const TOOL_BUDGET_EXHAUSTED = 'tool_budget_exhausted';
53	
54	export interface ChatOrchestrator {
55	  processMessage(session: ChatSession): Promise<string>;
56	  processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk>;
57	}
58	
59	export interface ChatOrchestratorOptions {
60	  maxToolRounds?: number;
61	  contextConfig?: Partial<ContextConfig>;
62	  promptBuilderOptions?: PromptBuilderOptions;
63	  hooks?: OrchestratorHooks;
64	  sessionStore?: SessionStore;
65	}
66	
67	interface ToolExecutionResult {
68	  clientMessages: OutgoingMessage[];
69	  suppressOutput: boolean;
70	}
71	export function createChatOrchestrator(
72	  provider: AIProvider,
73	  promptBuilder: PromptBuilder,
74	  toolRegistry?: ToolRegistry,
75	  options?: ChatOrchestratorOptions
76	): ChatOrchestrator {
77	  const maxToolRounds = normalizeToolRounds(options?.maxToolRounds);
78	  const contextConfig = createContextConfig(options?.contextConfig);
79	  const toolInstructions = toolRegistry?.getPromptInstructions();
80	  const baseSystemPrompt = promptBuilder.build({...options?.promptBuilderOptions, toolInstructions});
81	  const tools = toolRegistry?.getDefinitions();
82	  const hooks = options?.hooks;
83	  const sessionStore = options?.sessionStore;
84	
85	  return {
86	    async processMessage(session: ChatSession): Promise<string> {
87	      return collectText(this.processMessageStream(session));
88	    },
89	
90	    async *processMessageStream(session: ChatSession): AsyncGenerator<MessageChunk> {
91	      try {
92	        if (hooks?.beforeSession) await hooks.beforeSession(session);
93	
94	        let userMessage = lastUserContent(session);
95	
96	        if (hooks?.beforeUserInput) {
97	          userMessage = await rewriteUserMessage(session, userMessage, hooks.beforeUserInput);
98	        }
99	
100	        if (hooks?.afterUserInput) await hooks.afterUserInput(session, userMessage);
101	
102	        const systemPrompt = hooks?.beforeModelResponse
103	          ? await hooks.beforeModelResponse(session, baseSystemPrompt)
104	          : baseSystemPrompt;
105	
106	        const messages: Message[] = toMessages(session.entries, contextConfig);
107	        let totalUsage: UsageMetadata | undefined;
108	        let responseText = '';
109	
110	        // Bounded by the budget gate below, not the header: maxToolRounds executed rounds, maxToolRounds + 1 provider calls.
111	        for (let round = 0; ; round++) {
112	          log.info('orchestrator', 'starting round', {round});
113	          const pendingToolCalls: ToolCall[] = [];
114	
115	          const outcome = yield* streamRound(provider, {messages, systemPrompt, tools}, pendingToolCalls);
116	          responseText += outcome.text;
117	          totalUsage = accumulateUsage(totalUsage, outcome.usage);
118	
119	          if (!shouldContinueToolLoop(outcome.stopReason, pendingToolCalls, toolRegistry)) break;
120	          if (budgetSpent(round, maxToolRounds, pendingToolCalls)) {
121	            const budget = {maxToolRounds, requestedTools: pendingToolCalls.map(tc => tc.name)};
122	            responseText += yield* closeExhaustedTurn(session, budget, hooks?.onToolBudgetExhausted);
123	            break;
124	          }
125	
126	          log.info('orchestrator', 'executing tools', {tools: pendingToolCalls.map(tc => tc.name)});
127	          const {clientMessages, suppressOutput} = await executeToolCalls(
128	            pendingToolCalls,
129	            messages,
130	            session,
131	            toolCallRunner(toolRegistry!, session, hooks?.beforeToolCall)
132	          );
133	          log.info('orchestrator', 'tool execution complete', {
134	            clientMessageCount: clientMessages.length,
135	            clientMessageTypes: clientMessages.map(m => m.type),
136	            suppressOutput,
137	          });
138	
139	          if (clientMessages.length > 0) {
140	            yield {type: 'tool_result' as const, clientMessages};
141	          }
142	
143	          if (suppressOutput) {
144	            yield {type: 'suppress_output' as const};
145	          }
146	        }
147	
148	        if (hooks?.afterModelResponse) await hooks.afterModelResponse(session, responseText, totalUsage);
149	      } catch (error) {
150	        if (hooks?.onError) await hooks.onError(session, error instanceof Error ? error : asError(error));
151	        throw error;
152	      } finally {
153	        // Before both: a provider that threw mid-stream leaves an entry open, and nothing should persist it that way.
154	        commitStreamingEntries(session);
155	        try {
156	          if (hooks?.afterSession) await hooks.afterSession(session);
157	        } finally {
158	          await saveSession(sessionStore, session);
159	        }
160	      }
161	    },
162	  };
163	}
164	
165	// A negative budget means no tool rounds; a non-finite one, NaN included, falls back to the default rather than never ending.
166	function normalizeToolRounds(value: number | undefined): number {
167	  if (value === undefined || !Number.isFinite(value)) return DEFAULT_MAX_TOOL_ROUNDS;
168	  return Math.max(0, Math.floor(value));
169	}
170	
171	// Gates execution, not the provider call: a round nobody can read is never run, and the call that read the last one already has.
172	function budgetSpent(round: number, maxToolRounds: number, pendingToolCalls: ToolCall[]): boolean {
173	  if (round < maxToolRounds) return false;
174	  log.warn('orchestrator', 'tool budget exhausted', {
175	    maxToolRounds,
176	    requestedTools: pendingToolCalls.map(tc => tc.name),
177	  });
178	  return true;
179	}
180	
181	// The stop always follows the text: the round's own stop already committed its entry, and a bare text chunk would open one never committed.
182	async function* closeExhaustedTurn(
183	  session: ChatSession,
184	  budget: ToolBudgetInfo,
185	  hook?: OnToolBudgetExhausted
186	): AsyncGenerator<MessageChunk, string> {
187	  const sentence = (hook ? await hook(session, budget) : undefined) ?? '';
188	  if (sentence !== '') yield {type: 'text', text: sentence};
189	  yield {type: 'stop', stopReason: TOOL_BUDGET_EXHAUSTED};
190	  return sentence;
191	}
192	
193	interface RoundOutcome {
194	  stopReason: string;
195	  text: string;
196	  usage?: UsageMetadata;
197	}
198	
199	// `yield*` in the caller evaluates to this return, so the round's totals come back as data.
200	async function* streamRound(
201	  provider: AIProvider,
202	  request: SendMessageParams,
203	  pendingToolCalls: ToolCall[]
204	): AsyncGenerator<MessageChunk, RoundOutcome> {
205	  let stopReason = '';
206	  let text = '';
207	  let usage: UsageMetadata | undefined;
208	
209	  for await (const chunk of provider.sendMessage(request)) {
210	    yield chunk;
211	    collectToolCalls(chunk, pendingToolCalls);
212	    stopReason = extractStopReason(chunk) ?? stopReason;
213	    usage = extractUsage(chunk) ?? usage;
214	    if (chunk.type === 'text') text += chunk.text;
215	  }
216	
217	  return {stopReason, text, usage};
218	}
219	
220	// A changed message is also written back to the session's last user entry.
221	async function rewriteUserMessage(
222	  session: ChatSession,
223	  userMessage: string,
224	  hook: (session: ChatSession, userMessage: string) => Promise<string>
225	): Promise<string> {
226	  const modified = await hook(session, userMessage);
227	  if (modified === userMessage) return userMessage;
228	
229	  updateLastUserContent(session, modified);
230	  return modified;
231	}
232	
233	function lastUserContent(session: ChatSession): string {
234	  for (let i = session.entries.length - 1; i >= 0; i--) {
235	    const entry = session.entries[i];
236	    if (entry.role === 'user') return entry.content;
237	  }
238	  return '';
239	}
240	
241	function updateLastUserContent(session: ChatSession, content: string): void {
242	  for (let i = session.entries.length - 1; i >= 0; i--) {
243	    const entry = session.entries[i];
244	    if (entry.role === 'user') {
245	      entry.content = content;
246	      return;
247	    }
248	  }
249	}
250	
251	// One runner per round: the policy sees each known call before its executor, and an unknown name keeps the registry's own path.
252	function toolCallRunner(toolRegistry: ToolRegistry, session: ChatSession, beforeToolCall?: BeforeToolCall) {
253	  const context: ToolContext = {
254	    userId: session.userId,
255	    sessionId: session.sessionId,
256	    workspaceId: session.workspaceId,
257	    authHeaders: session.authHeaders,
258	  };
259	
260	  return async (tc: ToolCall): Promise<ToolResponse> => {
261	    const declined =
262	      beforeToolCall && toolRegistry.has(tc.name) ? await consultPolicy(beforeToolCall, session, tc) : undefined;
263	    return declined ?? toolRegistry.execute(tc.name, tc.input, context);
264	  };
265	}
266	
267	// A throwing policy declines its call rather than failing the turn: every tool_use must still be answered.
268	async function consultPolicy(
269	  policy: BeforeToolCall,
270	  session: ChatSession,
271	  tc: ToolCall
272	): Promise<ToolResponse | undefined> {
273	  try {
274	    return await policy(session, tc);
275	  } catch (error) {
276	    log.warn('orchestrator', 'beforeToolCall threw, so the call is declined', {
277	      tool: tc.name,
278	      errorType: error instanceof Error ? error.name : typeof error,
279	    });
280	    return {result: `The ${tc.name} call was declined and not performed.`};
281	  }
282	}
283	
284	// A rejection that is not an Error is wrapped for the hook alone; the caller still receives the original.
285	function asError(thrown: unknown): Error {
286	  return new Error(messageOf(thrown), {cause: thrown});
287	}
288	
289	// A string is already a message; anything else is stringified, with String() for what JSON cannot carry.
290	function messageOf(thrown: unknown): string {
291	  if (typeof thrown === 'string') return thrown;
292	  return tryStringify(thrown) ?? String(thrown);
293	}
294	
295	// JSON.stringify throws on circular structures and BigInt; null marks the values it cannot carry.
296	function tryStringify(value: unknown): string | null {
297	  try {
298	    return JSON.stringify(value);
299	  } catch {
300	    return null;
301	  }
302	}
303	
304	async function executeToolCalls(
305	  pendingToolCalls: ToolCall[],
306	  messages: Message[],
307	  session: ChatSession,
308	  runToolCall: (tc: ToolCall) => Promise<ToolResponse>
309	): Promise<ToolExecutionResult> {
310	  messages.push(buildToolCallMessages(pendingToolCalls));
311	
312	  const responses = await Promise.all(
313	    pendingToolCalls.map(async tc => {
314	      const response = await runToolCall(tc);
315	      return {tc, response};
316	    })
317	  );
318	
319	  const toolResults: ToolResultContent[] = responses.map(({tc, response}) => ({
320	    type: 'tool_result' as const,
321	    toolUseId: tc.id,
322	    content: response.result,
323	  }));
324	  messages.push({role: 'user', content: toolResults});
325	
326	  const rawClientMessages = responses.flatMap(({response}) => response.clientMessages ?? []);
327	
328	  return {
329	    clientMessages: assignEntryIndices(rawClientMessages, session),
330	    suppressOutput: responses.some(({response}) => response.suppressAssistantResponse === true),
331	  };
332	}
333	
334	function assignEntryIndices(clientMessages: OutgoingMessage[], session: ChatSession): OutgoingMessage[] {
335	  return clientMessages.map(msg => {
336	    if (msg.type !== 'entry_upsert') return msg;
337	    const index = appendEntry(session, msg.entry);
338	    return {...msg, index};
339	  });
340	}
341	
342	// Adds per-round token counts so the hook receives the total across all provider calls in the turn.
343	function accumulateUsage(acc: UsageMetadata | undefined, next: UsageMetadata | undefined): UsageMetadata | undefined {
344	  if (!acc) return next;
345	  if (!next) return acc;
346	  return {
347	    inputTokens: acc.inputTokens + next.inputTokens,
348	    outputTokens: acc.outputTokens + next.outputTokens,
349	    totalTokens: acc.totalTokens + next.totalTokens,
350	  };
351	}
352	
353	// A store outage is not a reason to fail the turn the customer already received.
354	async function saveSession(store: SessionStore | undefined, session: ChatSession): Promise<void> {
355	  if (!store?.save) return;
356	
357	  try {
358	    await store.save(session);
359	  } catch (error) {
360	    const message = error instanceof Error ? error.message : String(error);
361	    log.error('orchestrator', 'session save failed', {sessionId: session.sessionId, error: message});
362	  }
363	}
